package com.andye.warmod.antiair;import net.minecraft.util.Mth;import net.minecraft.world.phys.Vec3;public record AntiAirRoute(Vec3 start,Vec3 controlPoint1,Vec3 controlPoint2,Vec3 end,int durationTicks){public Vec3 position(double elapsed){double u=Mth.clamp(elapsed/durationTicks,0,1),v=1-u;return start.scale(v*v*v).add(controlPoint1.scale(3*v*v*u)).add(controlPoint2.scale(3*v*u*u)).add(end.scale(u*u*u));}public Vec3 velocity(double elapsed){double u=Mth.clamp(elapsed/durationTicks,0,1),v=1-u;return controlPoint1.subtract(start).scale(3*v*v).add(controlPoint2.subtract(controlPoint1).scale(6*v*u)).add(end.subtract(controlPoint2).scale(3*u*u)).scale(1.0/durationTicks);}public double arcLength(){double sum=0;Vec3 old=start;for(int i=1;i<=32;i++){Vec3 next=position(durationTicks*i/32.0);sum+=old.distanceTo(next);old=next;}return sum;}}